#!/usr/bin/env python3
"""Interactive 3D occupancy viewer with HTTP server.

Loads occupancy GT .npy files (state + semantic_id), generates static PNG
visualizations and interactive plotly HTML, then serves them via a local
HTTP server for browser viewing.

Usage:
    # From .npy files (generated by generate_occupancy_gt.py or validate_occupancy.py)
    python tools/vis/occupancy_3d_viewer.py --npy-dir /path/to/npy_dir

    # From an HDF5 episode file (reads occupancy_gt labels inline or from sidecar)
    python tools/vis/occupancy_3d_viewer.py --episode episode.hdf5 --frames 0,50,100

    # Specify port
    python tools/vis/occupancy_3d_viewer.py --npy-dir /tmp/occ --port 8900

    # Don't start server, just generate files
    python tools/vis/occupancy_3d_viewer.py --npy-dir /tmp/occ --no-server
"""

from __future__ import annotations

import argparse
import json
import os
import sys
from pathlib import Path

import numpy as np

# -- Constants (matching collector/occupancy.py) --
_UNKNOWN = 0
_FREE = 1
_OCCUPIED = 2

# Default per-object colors
_DEFAULT_COLORS = {
    0: "#ffffff",
    1: "#888888",
    2: "#e74c3c",
    3: "#3498db",
    4: "#2ecc71",
    5: "#f39c12",
    6: "#9b59b6",
    7: "#1abc9c",
    8: "#e67e22",
    9: "#34495e",
}

_DEFAULT_LABELS = {
    0: "free",
    1: "table",
    2: "obj_0",
    3: "obj_1",
    4: "obj_2",
    5: "obj_3",
    6: "obj_4",
    7: "obj_5",
    8: "obj_6",
    9: "obj_7",
}


# ---------------------------------------------------------------------------
# Data loading
# ---------------------------------------------------------------------------

def _discover_npy_files(npy_dir: str) -> dict[int, dict[str, str]]:
    """Scan directory for frame_XXXX_occupancy.npy + frame_XXXX_semantic.npy pairs.

    Returns {frame_idx: {"occ": path, "sem": path}}.
    """
    frames: dict[int, dict[str, str]] = {}
    for f in sorted(os.listdir(npy_dir)):
        if not f.endswith("_occupancy.npy"):
            continue
        prefix = f.removesuffix("_occupancy.npy")
        if not prefix.startswith("frame_"):
            continue
        try:
            fi = int(prefix.split("_")[1])
        except (IndexError, ValueError):
            continue
        occ_path = os.path.join(npy_dir, f)
        sem_path = os.path.join(npy_dir, f"{prefix}_semantic.npy")
        entry = {"occ": occ_path}
        if os.path.isfile(sem_path):
            entry["sem"] = sem_path
        frames[fi] = entry
    return frames


def _load_semantic_legend(episode_path: str, label_key: str = "occupancy_gt") -> dict[int, str] | None:
    """Try to read semantic_legend from HDF5 occupancy labels."""
    import h5py
    loc = None
    with h5py.File(episode_path, "r") as f:
        if "labels" in f and label_key in f["labels"] and "semantic_legend" in f["labels"][label_key]:
            legend_raw = f["labels"][label_key]["semantic_legend"][()]
            if isinstance(legend_raw, bytes):
                legend_raw = legend_raw.decode()
            return json.loads(legend_raw)

    # Try sidecar
    source = Path(episode_path)
    sidecar = source.parent / "derived" / f"{source.stem}_derived.hdf5"
    if sidecar.exists():
        import h5py
        with h5py.File(str(sidecar), "r") as f:
            if "labels" in f and label_key in f["labels"] and "semantic_legend" in f["labels"][label_key]:
                legend_raw = f["labels"][label_key]["semantic_legend"][()]
                if isinstance(legend_raw, bytes):
                    legend_raw = legend_raw.decode()
                return json.loads(legend_raw)
    return None


def load_frames_from_npy(npy_dir: str) -> tuple[dict, dict, dict]:
    """Load occupancy data from .npy files.

    Returns (frames, bounds, meta) where frames[fi] = {"occ": ndarray, "sem": ndarray}.
    """
    discovered = _discover_npy_files(npy_dir)
    if not discovered:
        raise FileNotFoundError(f"No frame_*_occupancy.npy files found in {npy_dir}")

    # Try to load bounds / voxel_size from summary JSON
    summary_path = os.path.join(npy_dir, "occupancy_summary.json")
    meta = {}
    if os.path.isfile(summary_path):
        with open(summary_path) as fh:
            meta = json.load(fh)

    bounds = meta.get("config", {}).get("bounds", [[-1.15, -0.35, 0.77], [1.15, 0.60, 1.10]])
    frames = {}
    for fi, paths in discovered.items():
        occ = np.load(paths["occ"])
        sem = np.load(paths["sem"]) if "sem" in paths else None
        frames[fi] = {"occ": occ, "sem": sem}

    return frames, bounds, meta


def load_frames_from_episode(
    episode_path: str,
    frame_indices: list[int],
    label_key: str = "occupancy_gt",
) -> tuple[dict, dict, dict]:
    """Load occupancy data from an HDF5 episode file.

    Returns (frames, bounds, meta).
    """
    import h5py

    # Find occupancy group
    occ_path = episode_path
    grp_key = f"labels/{label_key}"
    with h5py.File(episode_path, "r") as f:
        if grp_key not in f:
            source = Path(episode_path)
            sidecar = source.parent / "derived" / f"{source.stem}_derived.hdf5"
            if sidecar.exists():
                occ_path = str(sidecar)
            else:
                raise FileNotFoundError(
                    f"No '{label_key}' labels found in {episode_path} or its sidecar.\n"
                    f"  Run first: python tools/labels/generate_occupancy_gt.py {episode_path}"
                )

    with h5py.File(occ_path, "r") as f:
        grp = f[grp_key]
        state = np.asarray(grp["state"][:], dtype=np.uint8)
        bounds = np.asarray(grp["bounds"][()], dtype=np.float32).tolist()
        voxel_size = float(grp["voxel_size"][()])
        grid_shape = np.asarray(grp["grid_shape"][()], dtype=np.int32).tolist()
        sem = np.asarray(grp["semantic_id"][:], dtype=np.uint16) if "semantic_id" in grp else None

    frames = {}
    for fi in frame_indices:
        entry = {"occ": state[fi]}
        if sem is not None:
            entry["sem"] = sem[fi]
        frames[fi] = entry

    legend = _load_semantic_legend(episode_path, label_key)
    meta = {
        "config": {
            "bounds": bounds,
            "voxel_size": voxel_size,
            "grid_shape": grid_shape,
            "semantic_legend": legend,
        }
    }

    return frames, bounds, meta


# ---------------------------------------------------------------------------
# Visualization generators
# ---------------------------------------------------------------------------

def _build_semantic_labels(semantic_legend: dict | None, sem_ids: list[int]) -> dict[int, str]:
    """Merge legend from metadata with defaults for any missing IDs."""
    labels = dict(_DEFAULT_LABELS)
    if semantic_legend:
        for k, v in semantic_legend.items():
            labels[int(k)] = v
    return labels


def _make_colors(sem_ids: list[int]) -> dict[int, str]:
    """Assign colors to semantic IDs."""
    palette = list(_DEFAULT_COLORS.values())
    colors = {}
    for i, sid in enumerate(sorted(sem_ids)):
        colors[sid] = palette[i % len(palette)]
    return colors


def generate_3d_scatter_html(
    frames: dict,
    bounds: list,
    voxel_size: float,
    labels: dict[int, str],
    colors: dict[int, str],
    output_dir: str,
    max_per_object: int = 5000,
) -> list[str]:
    """Generate interactive plotly 3D HTML for each frame.

    Returns list of generated file paths.
    """
    import plotly.graph_objects as go

    paths = []
    for fi, data in sorted(frames.items()):
        occ = data["occ"]
        sem = data.get("sem")
        mask = occ == _OCCUPIED

        traces = []
        if sem is not None:
            sem_ids = sorted(np.unique(sem[mask]))
        else:
            sem_ids = [1]  # single "occupied" class

        for sid in sem_ids:
            obj_mask = mask & (sem == sid) if sem is not None else mask
            idx = np.argwhere(obj_mask)
            n = len(idx)
            if n == 0:
                continue
            rng = np.random.default_rng(42)
            if n > max_per_object:
                idx = idx[rng.choice(n, max_per_object, replace=False)]

            xs = bounds[0][0] + (idx[:, 0] + 0.5) * voxel_size
            ys = bounds[0][1] + (idx[:, 1] + 0.5) * voxel_size
            zs = bounds[0][2] + (idx[:, 2] + 0.5) * voxel_size

            c = colors.get(sid, "#cccccc")
            lbl = labels.get(sid, f"id_{sid}")
            traces.append(go.Scatter3d(
                x=xs, y=ys, z=zs, mode="markers",
                name=f"{lbl} ({n:,})",
                marker=dict(size=2.5, color=c, opacity=0.7),
            ))

        fig = go.Figure(data=traces)
        fig.update_layout(
            title=f"Frame {fi} — Occupancy GT (voxel={voxel_size:.3f}m)",
            scene=dict(
                xaxis_title="X (m)", yaxis_title="Y (m)", zaxis_title="Z (m)",
                xaxis=dict(range=[bounds[0][0], bounds[1][0]]),
                yaxis=dict(range=[bounds[0][1], bounds[1][1]]),
                zaxis=dict(range=[bounds[0][2], bounds[1][2]]),
                aspectmode="data",
            ),
            margin=dict(l=0, r=0, b=0, t=40),
        )
        path = os.path.join(output_dir, f"frame_{fi:04d}_occupancy.html")
        fig.write_html(path)
        paths.append(path)

    return paths


def generate_xy_slice_png(
    frames: dict,
    bounds: list,
    grid_shape: tuple,
    labels: dict[int, str],
    colors: dict[int, str],
    output_dir: str,
    z_slice: int = 5,
) -> str:
    """Generate an XY slice comparison PNG across all frames."""
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt

    n = len(frames)
    ncols = min(n, 5)
    nrows = (n + ncols - 1) // ncols
    fig, axes = plt.subplots(nrows, ncols, figsize=(4 * ncols, 3.5 * nrows), squeeze=False)

    for idx, (fi, data) in enumerate(sorted(frames.items())):
        r, c = divmod(idx, ncols)
        ax = axes[r][c]
        sem = data.get("sem")
        if sem is None:
            ax.text(0.5, 0.5, "no semantic data", transform=ax.transAxes, ha="center")
            continue

        z = min(z_slice, sem.shape[2] - 1)
        xy_sem = sem[:, :, z]
        rgb = np.ones((sem.shape[0], sem.shape[1], 3))
        for sid, color in colors.items():
            mask_xy = xy_sem == sid
            c_rgb = matplotlib.colors.to_rgb(color)
            for ch in range(3):
                rgb[mask_xy, ch] = c_rgb[ch]

        ax.imshow(rgb.transpose(1, 0, 2), origin="lower",
                  extent=[bounds[0][0], bounds[1][0], bounds[0][1], bounds[1][1]])
        ax.set_xlabel("X (m)")
        ax.set_ylabel("Y (m)")
        z_world = bounds[0][2] + (z + 0.5) * (bounds[1][2] - bounds[0][2]) / grid_shape[2]
        ax.set_title(f"Frame {fi} — z≈{z_world:.3f}m")

    # Hide unused axes
    for j in range(n, nrows * ncols):
        r, c = divmod(j, ncols)
        axes[r][c].set_visible(False)

    fig.suptitle("Occupancy GT — XY Slice", fontsize=14, fontweight="bold")
    fig.tight_layout()
    path = os.path.join(output_dir, "occupancy_xy_slices.png")
    fig.savefig(path, dpi=150, bbox_inches="tight")
    plt.close(fig)
    return path


def generate_bar_chart_png(
    frames: dict,
    labels: dict[int, str],
    colors: dict[int, str],
    output_dir: str,
) -> str:
    """Generate per-object voxel count bar chart across frames."""
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt

    # Determine all semantic IDs present
    all_sids = set()
    for data in frames.values():
        sem = data.get("sem")
        if sem is not None:
            occ_mask = data["occ"] == _OCCUPIED
            all_sids.update(np.unique(sem[occ_mask]))
    all_sids = sorted(all_sids)

    frame_list = sorted(frames.keys())
    counts = {sid: [] for sid in all_sids}
    for fi in frame_list:
        data = frames[fi]
        sem = data.get("sem")
        occ_mask = data["occ"] == _OCCUPIED
        for sid in all_sids:
            if sem is not None:
                counts[sid].append(int(np.sum((sem == sid) & occ_mask)))
            else:
                counts[sid].append(int(np.sum(occ_mask)))

    fig, ax = plt.subplots(figsize=(max(8, 2 * len(frame_list)), 5))
    x = np.arange(len(frame_list))
    width = 0.8 / len(all_sids) if all_sids else 0.8
    for j, sid in enumerate(all_sids):
        ax.bar(x + j * width, counts[sid], width,
               label=labels.get(sid, f"id_{sid}"),
               color=colors.get(sid, "#cccccc"))

    ax.set_xticks(x + width * (len(all_sids) - 1) / 2)
    ax.set_xticklabels([str(f) for f in frame_list])
    ax.set_xlabel("Frame")
    ax.set_ylabel("Voxel count")
    ax.set_title("Occupied voxels per object across frames")
    ax.legend(fontsize=9)
    fig.tight_layout()
    path = os.path.join(output_dir, "occupancy_bar_chart.png")
    fig.savefig(path, dpi=150, bbox_inches="tight")
    plt.close(fig)
    return path


def generate_viewer_html(
    frame_list: list[int],
    static_images: dict[str, str],
    labels: dict[int, str],
    colors: dict[int, str],
    meta: dict,
    output_dir: str,
) -> str:
    """Generate a master viewer HTML page linking all visualizations."""
    links_3d = "".join(
        f'<li><a href="frame_{fi:04d}_occupancy.html" target="_blank">Frame {fi} — interactive 3D</a></li>'
        for fi in sorted(frame_list)
    )
    cards = "".join(
        f'<div class="card"><h3>{name}</h3>'
        f'<a href="{fname}" target="_blank"><img src="{fname}"></a></div>'
        for name, fname in static_images.items()
    )
    legend = " &nbsp; ".join(
        f'<span style="color:{colors.get(sid,"#ccc")}">⬤ {labels.get(sid,f"id_{sid}")}</span>'
        for sid in sorted(labels.keys()) if sid not in (0, 1)
    )

    cfg = meta.get("config", {})
    bounds = cfg.get("bounds", [[0, 0, 0], [1, 1, 1]])
    vs = cfg.get("voxel_size", "?")
    gs = cfg.get("grid_shape", "?")

    html = f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8"><title>Occupancy GT Viewer</title>
<style>
  * {{ box-sizing: border-box; }}
  body {{ font-family: -apple-system, sans-serif; margin: 20px; background: #1a1a2e; color: #eee; }}
  h1 {{ color: #e94560; }}
  h2 {{ color: #0f3460; border-bottom: 2px solid #0f3460; padding-bottom: 4px; }}
  .grid {{ display: grid; grid-template-columns: repeat(auto-fit, minmax(400px, 1fr)); gap: 16px; }}
  .card {{ background: #16213e; border-radius: 8px; padding: 16px; }}
  .card h3 {{ margin-top: 0; font-size: 14px; }}
  .card img {{ width: 100%; border-radius: 4px; }}
  a {{ color: #fff; background: #e94560; padding: 8px 16px; border-radius: 4px;
       text-decoration: none; display: inline-block; margin: 4px; }}
  a:hover {{ background: #c23152; }}
  ul {{ list-style: none; padding: 0; }}
  li {{ margin: 8px 0; }}
  .info {{ background: #16213e; border-radius: 8px; padding: 12px; margin: 12px 0; }}
  .info code {{ color: #e94560; }}
</style>
</head>
<body>
<h1>🎯 Occupancy GT Viewer</h1>
<div class="info">
  Voxel size: <code>{vs}m</code> |
  Grid: <code>{gs}</code> |
  Bounds: <code>x[{bounds[0][0]:.2f},{bounds[1][0]:.2f}] y[{bounds[0][1]:.2f},{bounds[1][1]:.2f}] z[{bounds[0][2]:.2f},{bounds[1][2]:.2f}]</code>
</div>

<h2>🔴 Interactive 3D Views (click to open — drag to rotate, scroll to zoom)</h2>
<ul>{links_3d}</ul>

<h2>📊 Static Visualizations</h2>
<div class="grid">{cards}</div>

<h2>🎨 Legend</h2>
<p>{legend}</p>

<p style="margin-top:30px;color:#666;font-size:12px">Generated by tools/vis/occupancy_3d_viewer.py</p>
</body>
</html>"""
    path = os.path.join(output_dir, "occupancy_viewer.html")
    with open(path, "w") as f:
        f.write(html)
    return path


# ---------------------------------------------------------------------------
# HTTP server
# ---------------------------------------------------------------------------

def start_http_server(directory: str, port: int) -> None:
    """Start a simple HTTP server in *directory* on *port*."""
    import http.server
    import socket
    import socketserver

    # Get local IP
    host_ip = "127.0.0.1"
    try:
        s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        s.connect(("8.8.8.8", 80))
        host_ip = s.getsockname()[0]
        s.close()
    except Exception:
        pass

    os.chdir(directory)

    class Handler(http.server.SimpleHTTPRequestHandler):
        def log_message(self, fmt, *args):
            print(f"  [HTTP] {args[0]}")

    try:
        with socketserver.TCPServer(("", port), Handler) as httpd:
            print(f"\n{'='*60}")
            print(f"  🌐 HTTP server started!")
            print(f"  Local:   http://127.0.0.1:{port}/occupancy_viewer.html")
            print(f"  Network: http://{host_ip}:{port}/occupancy_viewer.html")
            print(f"  Press Ctrl+C to stop.")
            print(f"{'='*60}\n")
            httpd.serve_forever()
    except KeyboardInterrupt:
        print("\n[INFO] Server stopped.")


# ---------------------------------------------------------------------------
# CLI
# ---------------------------------------------------------------------------

def main() -> None:
    parser = argparse.ArgumentParser(
        description="Interactive 3D occupancy viewer with HTTP server."
    )
    # Input sources
    group = parser.add_mutually_exclusive_group(required=True)
    group.add_argument("--npy-dir", type=str, default=None,
                       help="Directory containing frame_*_occupancy.npy files")
    group.add_argument("--episode", type=str, default=None,
                       help="HDF5 episode file with occupancy labels")

    parser.add_argument("--frames", type=str, default=None,
                        help="Comma-separated frame indices (for --episode mode, default: 0)")
    parser.add_argument("--label-key", type=str, default="occupancy_gt",
                        choices=["occupancy_gt", "occupancy_tsdf"],
                        help="Label group key (for --episode mode, default: occupancy_gt)")
    parser.add_argument("--output-dir", type=str, default=None,
                        help="Output directory (default: same as input)")

    # Visualization options
    parser.add_argument("--z-slice", type=int, default=5,
                        help="Z-index for XY slice PNG (default: 5)")
    parser.add_argument("--max-per-object", type=int, default=5000,
                        help="Max points per object in interactive HTML (default: 5000)")

    # Server options
    parser.add_argument("--port", type=int, default=8899,
                        help="HTTP server port (default: 8899)")
    parser.add_argument("--no-server", action="store_true",
                        help="Generate files only, don't start server")

    args = parser.parse_args()

    # --- Load data ---
    if args.npy_dir:
        frames, bounds, meta = load_frames_from_npy(args.npy_dir)
        output_dir = args.output_dir or args.npy_dir
    else:
        frame_indices = [int(x.strip()) for x in args.frames.split(",")] if args.frames else [0]
        frames, bounds, meta = load_frames_from_episode(
            args.episode, frame_indices, label_key=args.label_key,
        )
        output_dir = args.output_dir or os.path.dirname(args.episode)

    os.makedirs(output_dir, exist_ok=True)
    frame_list = sorted(frames.keys())
    print(f"[INFO] Loaded {len(frame_list)} frames: {frame_list}")

    # --- Determine labels and colors ---
    all_sids: set[int] = set()
    for data in frames.values():
        sem = data.get("sem")
        occ = data["occ"]
        if sem is not None:
            mask = occ == _OCCUPIED
            all_sids.update(int(x) for x in np.unique(sem[mask]))

    semantic_legend = meta.get("config", {}).get("semantic_legend")
    labels = _build_semantic_labels(semantic_legend, sorted(all_sids))
    colors = _make_colors(sorted(all_sids))

    cfg = meta.get("config", {})
    grid_shape = cfg.get("grid_shape", frames[frame_list[0]]["occ"].shape)
    voxel_size = cfg.get("voxel_size", 0.01)

    print(f"[INFO] Bounds: {bounds}")
    print(f"[INFO] Grid shape: {grid_shape}, voxel_size: {voxel_size}")
    print(f"[INFO] Objects found: {[(sid, labels.get(sid, f'id_{sid}')) for sid in sorted(all_sids)]}")

    # --- Generate visualizations ---
    print("\n[INFO] Generating visualizations...")

    # Interactive 3D HTML
    html_paths = generate_3d_scatter_html(
        frames, bounds, voxel_size, labels, colors, output_dir,
        max_per_object=args.max_per_object,
    )
    for p in html_paths:
        print(f"  [OK] {p}")

    # XY slice PNG
    xy_path = generate_xy_slice_png(
        frames, bounds, grid_shape, labels, colors, output_dir, z_slice=args.z_slice,
    )
    print(f"  [OK] {xy_path}")

    # Bar chart PNG
    bar_path = generate_bar_chart_png(frames, labels, colors, output_dir)
    print(f"  [OK] {bar_path}")

    # Master viewer HTML
    static_images = {
        "XY Slice (top-down)": os.path.basename(xy_path),
        "Bar Chart (voxel counts)": os.path.basename(bar_path),
    }
    viewer_path = generate_viewer_html(
        frame_list, static_images, labels, colors, meta, output_dir,
    )
    print(f"  [OK] {viewer_path}")

    # --- Start server ---
    if not args.no_server:
        start_http_server(output_dir, args.port)
    else:
        print(f"\n[INFO] All files generated in: {output_dir}")
        print(f"[INFO] To serve, run: python -m http.server {args.port} -d {output_dir}")


if __name__ == "__main__":
    main()
